import pandas as pd,numpy as np
from pathlib import Path
from floodwatch.core.features import tcwv_percentile
r=Path('outputs/operational');e=pd.read_csv('data/processed/stage1b_daily.csv',index_col=0,parse_dates=True);g=pd.read_csv(r/'gfs_daily.csv',index_col=0,parse_dates=True);g=g.reindex(pd.date_range(g.index.min(),g.index.max()));dates=g.index[g.index.month.isin([6,7,8,9,10])];rows=[]
for n in [3,7,14]:
 a=e.precip_mm.rolling(n,min_periods=n).sum();b=g.precip_mm.rolling(n,min_periods=n).sum();x=tcwv_percentile(a.reindex(dates),a.loc['2001':'2019']);y=tcwv_percentile(b.reindex(dates),b.reindex(dates));z=pd.concat([x,y],axis=1).dropna();corr=z.iloc[:,0].corr(z.iloc[:,1]);rows.append(dict(variable=f'rain_{n}d',correlation=corr,n_days=len(z),decision='usable' if corr>=.7 else 'WARN usable' if corr>=.5 else 'dropped'))
z=pd.concat([g.tcwv_mm.rename('gfs'),e.tcwv_mm.rename('era5')],axis=1);z=z.loc[z.index.month.isin([6,7,8,9,10])].dropna();fit=z.loc['2024'];test=z.loc['2025'];q=np.linspace(0,1,101);xp=np.quantile(fit.gfs,q);yp=np.quantile(fit.era5,q);xp,indices=np.unique(xp,return_index=True);yp=yp[indices];mapped=pd.Series(np.interp(test.gfs,xp,yp),index=test.index);a=tcwv_percentile(mapped,e.tcwv_mm.loc['2001':'2019']);b=tcwv_percentile(test.era5,e.tcwv_mm.loc['2001':'2019']);corr=a.corr(b);rows.append(dict(variable='tcwv_2025_OOS',correlation=corr,n_days=len(test),decision='usable' if corr>=.7 else 'dropped'));pd.DataFrame(rows).to_csv(r/'transfer_correlations.csv',index=False);print(pd.DataFrame(rows).to_string(index=False));print('TCWV fit days',len(fit));pd.DataFrame({'mapped_gfs_pct':a,'era5_pct':b}).to_csv(r/'tcwv_oos.csv')
